// IQDI «People First — Human Centered» brand rules (TEST ONLY project). The masters in
// assets/branding/people-first/ are generated by tools/branding/people_first.py; these tests pin the
// owner's decisions (one human symbol, no palm/arch/lion/seal/map motifs, Light/Dark/Monochrome/compact
// from one geometry, tagline never inside icons) and the safety rules (real vectors, no raster, no script,
// no official-endorsement wording), plus what the apps actually ship (manifest, favicons, tokens).
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { contrastRatio, tokens } from '../packages/ui/src/tokens.ts';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const brand = path.join(root, 'assets', 'branding', 'people-first');
const read = (f: string) => readFileSync(path.join(brand, f), 'utf8');
const MASTERS = readdirSync(brand).filter((f) => f.endsWith('.svg'));
const pathData = (svg: string): string[] => [...svg.matchAll(/\sd="([^"]+)"/g)].map((m) => m[1] ?? '');
const pngSize = (file: string) => { const b = readFileSync(file); return b.readUInt32BE(0) === 0x89504e47 ? { w: b.readUInt32BE(16), h: b.readUInt32BE(20) } : null; };
const viewBox = (svg: string): number[] => (/viewBox="([^"]+)"/.exec(svg)?.[1] ?? '0 0 1 1').split(/\s+/).map(Number);
// Shared symbol geometry (see the generator): the head circle and the gold leaf's outline.
const HEAD = '<circle cx="340" cy="120" r="106"';
const GOLD = 'M602 185 C470 215 330 300 285 420';
// Markers of the archived identity that must not reach the new brand.
const OLD_MOTIFS = ['M2 30 C6 20 14 12 26 10', 'M446 446 C600 446', '-tiles"', 'M262 794 C292 758'];

describe('People First masters are real, safe vectors', () => {
  it('the requested asset set exists', () => {
    for (const f of ['iqdi-primary-light.svg', 'iqdi-primary-dark.svg', 'iqdi-primary-monochrome.svg', 'iqdi-horizontal-light.svg', 'iqdi-horizontal-dark.svg',
      'iqdi-horizontal-monochrome.svg', 'iqdi-symbol-light.svg', 'iqdi-symbol-dark.svg', 'iqdi-symbol-monochrome.svg', 'iqdi-symbol-compact.svg',
      'iqdi-symbol-compact-dark.svg', 'iqdi-app-icon-light.svg', 'iqdi-app-icon-dark.svg', 'iqdi-favicon.svg']) expect(MASTERS).toContain(f);
  });

  it.each(MASTERS)('%s: viewBox + <title>, no raster, no script, no live text, bounded size', (file) => {
    const svg = read(file);
    expect(svg).toMatch(/<svg xmlns="http:\/\/www\.w3\.org\/2000\/svg" viewBox="[\d. ]+"/);
    expect(svg).toMatch(/<title id="[^"]+">IQDI — Iraqi Digital Identity[^<]*TEST ONLY/);
    expect(svg).not.toMatch(/<image|data:image\/(png|jpe?g|webp)|base64,/i);
    expect(svg).not.toMatch(/<script|\son[a-z]+=|javascript:|xlink:href="http|href="http/i);
    expect(svg).not.toMatch(/<text[\s>]/);
    expect(svg.length).toBeLessThan(70_000);
    expect(pathData(svg).length).toBeLessThan(40);
  });

  it.each(MASTERS)('%s: no wording implying government endorsement and no archived motifs', (file) => {
    const svg = read(file);
    expect(svg).not.toMatch(/وزارة|جمهورية العراق|Ministry|Republic of Iraq|Government of Iraq|official/i);
    for (const m of OLD_MOTIFS) expect(svg).not.toContain(m);
  });

  it('every symbol-bearing file uses the same human symbol (head circle + gold leaf)', () => {
    for (const f of MASTERS) {
      const svg = read(f);
      expect(svg, f).toContain(HEAD.replace('r="106"', f.includes('compact') || f.includes('favicon') ? 'r="112"' : 'r="106"'));
      expect(svg, f).toContain(GOLD);
    }
  });

  it('Light and Dark share one geometry (same paths, same order); only paint differs', () => {
    for (const kind of ['symbol', 'primary', 'horizontal', 'app-icon']) {
      expect(pathData(read(`iqdi-${kind}-dark.svg`))).toEqual(pathData(read(`iqdi-${kind}-light.svg`)));
      expect(read(`iqdi-${kind}-dark.svg`)).not.toEqual(read(`iqdi-${kind}-light.svg`));
    }
    expect(pathData(read('iqdi-symbol-compact-dark.svg'))).toEqual(pathData(read('iqdi-symbol-compact.svg')));
  });

  it('Dark is its own treatment: lighter body and band than the night background, light lettering', () => {
    const dark = read('iqdi-primary-dark.svg');
    expect(dark).toContain('#123B69'); // body lighter than the night background #0B1F38
    expect(dark).toContain('#33A0F2'); // brighter blue band
    expect(dark).toMatch(/fill="#FFFFFF"/); // IQDI wordmark
    expect(contrastRatio('#FFFFFF', tokens.brand.night)).toBeGreaterThanOrEqual(7);
  });

  it('monochrome masters use one colour (currentColor) with knock-outs, no gradients or hex colours', () => {
    for (const f of ['iqdi-symbol-monochrome.svg', 'iqdi-primary-monochrome.svg', 'iqdi-horizontal-monochrome.svg']) {
      const svg = read(f);
      expect(svg).toContain('fill="currentColor"');
      expect(svg).toContain('stroke="black"'); // the knock-out gaps that keep band, body and gold apart
      expect(svg).not.toMatch(/Gradient|#[0-9a-f]{6}/i);
    }
  });

  it('the tagline appears only in the primary logo; icons, symbols and the compact mark carry no lettering', () => {
    const lettered = (svg: string) => pathData(svg).some((d) => d.length > 2000); // outlined text runs are long paths
    for (const f of MASTERS) {
      const hasText = lettered(read(f));
      if (f.startsWith('iqdi-primary') || f.startsWith('iqdi-horizontal')) expect(hasText, f).toBe(true);
      else expect(hasText, f).toBe(false);
    }
    // the horizontal lockup has three text runs (IQDI, Arabic, English) and no tagline; the primary colour logos have four
    expect(pathData(read('iqdi-horizontal-light.svg')).filter((d) => d.length > 2000)).toHaveLength(3);
    expect(pathData(read('iqdi-primary-light.svg')).filter((d) => d.length > 2000)).toHaveLength(4);
  });

  it('the compact mark is the same symbol simplified: flat colours, no fold tab, no gradients', () => {
    const c = read('iqdi-symbol-compact.svg');
    expect(c).not.toMatch(/Gradient/);
    expect(c).not.toContain('M80 195 L116 176'); // fold tab dropped
    expect(c).toContain('stroke-width="34"'); // wider gap around the gold leaf
  });
});

describe('People First rasters, app icons and favicons', () => {
  it('every PNG derivative has the width its name states and its master aspect ratio', () => {
    const dir = path.join(brand, 'png');
    const files = readdirSync(dir).filter((f) => f.endsWith('.png'));
    expect(files.length).toBeGreaterThanOrEqual(40);
    for (const f of files) {
      const m = /^(.*)-(\d+)\.png$/.exec(f);
      const s = pngSize(path.join(dir, f));
      const [, , w = 1, h = 1] = viewBox(read(`${m?.[1]}.svg`));
      expect(s?.w, f).toBe(Number(m?.[2]));
      expect(Math.abs((s?.h ?? 0) - Math.round((s?.w ?? 0) * (h / w))), f).toBeLessThanOrEqual(1);
    }
    for (const n of [16, 24, 32, 48, 64, 128, 256, 512, 1024]) expect(files).toContain(`iqdi-app-icon-light-${n}.png`);
  });

  it('wallet manifest icons exist at their declared sizes; both apps ship the People First favicon', () => {
    const manifest = JSON.parse(readFileSync(path.join(root, 'apps/wallet-web/public/manifest.webmanifest'), 'utf8')) as { icons: { src: string; sizes: string; purpose: string }[]; theme_color: string };
    expect(manifest.theme_color).toBe(tokens.brand.navy);
    for (const icon of manifest.icons) {
      const s = pngSize(path.join(root, 'apps/wallet-web/public', icon.src));
      expect(`${s?.w}x${s?.h}`).toBe(icon.sizes);
    }
    for (const app of ['wallet-web', 'verifier-web']) {
      expect(readFileSync(path.join(root, 'apps', app, 'public/favicon.svg'), 'utf8')).toBe(read('iqdi-favicon.svg'));
      expect(pngSize(path.join(root, 'apps', app, 'public/favicon-32.png'))).toEqual({ w: 32, h: 32 });
      const html = readFileSync(path.join(root, 'apps', app, 'index.html'), 'utf8');
      expect(html).not.toMatch(/rel="icon" href="data:/);
      expect(html).toContain(`<meta name="theme-color" content="${tokens.brand.navy}" />`);
    }
    expect(existsSync(path.join(root, 'apps/wallet-web/public/sw.js'))).toBe(false); // still no service worker
  });

  it('no live app file references the archived identity', () => {
    const scan = (dir: string): string[] => readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
      const p = path.join(dir, e.name);
      if (e.isDirectory()) return ['node_modules', 'dist'].includes(e.name) ? [] : scan(p);
      return /\.(tsx?|css|html|webmanifest)$/.test(e.name) ? [p] : [];
    });
    for (const f of [...scan(path.join(root, 'apps')), ...scan(path.join(root, 'packages', 'ui', 'src'))]) {
      expect(readFileSync(f, 'utf8'), f).not.toMatch(/assets\/branding\/(?!people-first)|iqdi-(mark|logo)-(original|dark)|iqdi-app-icon\.svg/);
    }
  });
});

describe('People First brand tokens', () => {
  it('text pairs meet WCAG; gold is restricted to artwork and large text on light backgrounds', () => {
    const b = tokens.brand;
    expect(contrastRatio(b.navy, b.offWhite)).toBeGreaterThanOrEqual(7);
    expect(contrastRatio(b.blue, b.offWhite)).toBeGreaterThanOrEqual(4.5);
    expect(contrastRatio(b.goldOnDark, b.night)).toBeGreaterThanOrEqual(7);
    expect(contrastRatio(b.gold, b.offWhite)).toBeLessThan(3); // documented: never small gold text on off-white
  });
});
